/**
 * Snapshot for the `ViewId::AppRoot` projection.
 */
public struct AppRootSnapshot {
    /**
     * Which top-level screen to render.
     */
    public var routeKind: RouteKind
    /**
     * Whether a session secret is currently in memory.
     */
    public var sessionPresent: Bool
    /**
     * Whether the user has completed onboarding.
     */
    public var onboardingComplete: Bool
    /**
     * The most recently minted `nostrconnect://` URI, or `None` when no
     * NostrConnect sign-in is in progress. The iOS QR-code sheet renders this
     * directly. Cleared when `IdentityChanged` fires or on `Logout`.
     * Bounded: one string ≤ 512 bytes (NIP-46 spec limit).
     */
    public var nostrconnectUri: String?
    /**
     * Raw error from a failed restore or sign-in (`SessionState::RestoreFailed`
     * / `SignInFailed`), or `None`. Gives LoginView's inline error a kernel
     * source. Naturally cleared (→ `None`) the moment the session transitions
     * to a new attempt (Restoring/SigningIn), success (Present), or Absent — so
     * no explicit clear-on-route-change is needed. D1: raw error; Swift formats
     * the display copy.
     */
    public var authError: String?
    /**
     * Raw 64-char hex pubkey of the active session. `None` when no session is
     * present. Exposed so Swift can build `CurrentUser` after kernel sign-in
     * without a bespoke lane call. D1: raw hex; Swift formats npub for display.
     */
    public var activePubkeyHex: String?
    /**
     * bech32 `npub` of the active session (for Settings / KeysView display).
     * Pre-encoded in Rust so Swift avoids a bespoke bech32 dependency.
     * `None` when no session is present.
     */
    public var activePubkeyNpub: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Which top-level screen to render.
         */routeKind: RouteKind,
        /**
         * Whether a session secret is currently in memory.
         */sessionPresent: Bool,
        /**
         * Whether the user has completed onboarding.
         */onboardingComplete: Bool,
        /**
         * The most recently minted `nostrconnect://` URI, or `None` when no
         * NostrConnect sign-in is in progress. The iOS QR-code sheet renders this
         * directly. Cleared when `IdentityChanged` fires or on `Logout`.
         * Bounded: one string ≤ 512 bytes (NIP-46 spec limit).
         */nostrconnectUri: String?,
        /**
         * Raw error from a failed restore or sign-in (`SessionState::RestoreFailed`
         * / `SignInFailed`), or `None`. Gives LoginView's inline error a kernel
         * source. Naturally cleared (→ `None`) the moment the session transitions
         * to a new attempt (Restoring/SigningIn), success (Present), or Absent — so
         * no explicit clear-on-route-change is needed. D1: raw error; Swift formats
         * the display copy.
         */authError: String?,
        /**
         * Raw 64-char hex pubkey of the active session. `None` when no session is
         * present. Exposed so Swift can build `CurrentUser` after kernel sign-in
         * without a bespoke lane call. D1: raw hex; Swift formats npub for display.
         */activePubkeyHex: String?,
        /**
         * bech32 `npub` of the active session (for Settings / KeysView display).
         * Pre-encoded in Rust so Swift avoids a bespoke bech32 dependency.
         * `None` when no session is present.
         */activePubkeyNpub: String?) {
        self.routeKind = routeKind
        self.sessionPresent = sessionPresent
        self.onboardingComplete = onboardingComplete
        self.nostrconnectUri = nostrconnectUri
        self.authError = authError
        self.activePubkeyHex = activePubkeyHex
        self.activePubkeyNpub = activePubkeyNpub
    }
}

#if compiler(>=6)
extension AppRootSnapshot: Sendable {}
#endif


extension AppRootSnapshot: Equatable, Hashable {
    public static func ==(lhs: AppRootSnapshot, rhs: AppRootSnapshot) -> Bool {
        if lhs.routeKind != rhs.routeKind {
            return false
        }
        if lhs.sessionPresent != rhs.sessionPresent {
            return false
        }
        if lhs.onboardingComplete != rhs.onboardingComplete {
            return false
        }
        if lhs.nostrconnectUri != rhs.nostrconnectUri {
            return false
        }
        if lhs.authError != rhs.authError {
            return false
        }
        if lhs.activePubkeyHex != rhs.activePubkeyHex {
            return false
        }
        if lhs.activePubkeyNpub != rhs.activePubkeyNpub {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(routeKind)
        hasher.combine(sessionPresent)
        hasher.combine(onboardingComplete)
        hasher.combine(nostrconnectUri)
        hasher.combine(authError)
        hasher.combine(activePubkeyHex)
        hasher.combine(activePubkeyNpub)
    }
}



