     */
    case url(
        /**
         * Raw HTTP/HTTPS URL string.
         */url: String
    )
    /**
     * `["t", <hashtag>]` — a bookmarked hashtag.
     */
    case hashtag(
        /**
         * Normalised lowercase hashtag string (without `#` prefix).
         */hashtag: String
