        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .capturePage

        case 2: return .scanBarcode

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CameraOp, into buf: inout [UInt8]) {
        switch value {


